// Database.cpp
#include "data/Database.h"

#include <sqlite3.h>

#include "SchemaSql.h"  // generated by CMake from db/schema.sql
#include "domain/Exceptions.h"
#include "domain/Time.h"

namespace lms {

namespace {
[[noreturn]] void fail(sqlite3* db, const std::string& what) {
    throw DatabaseException(what + ": " + (db != nullptr ? sqlite3_errmsg(db) : "unknown error"));
}
}  // namespace

// ---------------------------------------------------------------- Database

Database::Database(const std::string& path) {
    if (sqlite3_open(path.c_str(), &db_) != SQLITE_OK) {
        std::string message = "Could not open database '" + path + "'";
        if (db_ != nullptr) {
            message += std::string(": ") + sqlite3_errmsg(db_);
            sqlite3_close(db_);
            db_ = nullptr;
        }
        throw DatabaseException(message);
    }
    configure();
    ensureSchema();
}

Database::~Database() {
    if (db_ != nullptr) {
        sqlite3_close(db_);
    }
}

void Database::configure() {
    // WAL plus a busy timeout lets several users work at once without "database is
    // locked" errors (NFR-02, risk R2). The timeout must be set FIRST: setting WAL mode
    // needs a lock, and without the timeout a connection opened while someone else is
    // saving gives up at once instead of waiting (defect D-09, found by CI).
    sqlite3_busy_timeout(db_, 5000);
    executeScript("PRAGMA foreign_keys = ON;");  // off by default in SQLite
    executeScript("PRAGMA journal_mode = WAL;");
}

void Database::ensureSchema() {
    Statement check(*this,
                    "SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = 'app_user'");
    check.step();
    if (check.getInt(0) == 0) {
        executeScript("BEGIN;");
        try {
            executeScript(kSchemaSql);
            executeScript("COMMIT;");
        } catch (...) {
            sqlite3_exec(db_, "ROLLBACK;", nullptr, nullptr, nullptr);
            throw;
        }
    }
}

std::int64_t Database::lastInsertId() const {
    return sqlite3_last_insert_rowid(db_);
}

void Database::executeScript(const std::string& sql) {
    char* error = nullptr;
    if (sqlite3_exec(db_, sql.c_str(), nullptr, nullptr, &error) != SQLITE_OK) {
        std::string message = error != nullptr ? error : "unknown error";
        sqlite3_free(error);
        throw DatabaseException("SQL script failed: " + message);
    }
}

namespace {
// Copies the whole of one open database into another using SQLite's online backup API.
void copyDatabase(sqlite3* from, sqlite3* to) {
    sqlite3_backup* backup = sqlite3_backup_init(to, "main", from, "main");
    if (backup == nullptr) {
        fail(to, "Backup could not start");
    }
    int rc = sqlite3_backup_step(backup, -1);
    sqlite3_backup_finish(backup);
    if (rc != SQLITE_DONE) {
        fail(to, "Backup failed");
    }
}
}  // namespace

void Database::backupTo(const std::string& path) {
    sqlite3* target = nullptr;
    if (sqlite3_open(path.c_str(), &target) != SQLITE_OK) {
        sqlite3_close(target);
        throw DatabaseException("Could not create backup file '" + path + "'");
    }
    try {
        copyDatabase(db_, target);
    } catch (...) {
        sqlite3_close(target);
        throw;
    }
    sqlite3_close(target);
}

void Database::restoreFrom(const std::string& path) {
    sqlite3* source = nullptr;
    if (sqlite3_open_v2(path.c_str(), &source, SQLITE_OPEN_READONLY, nullptr) != SQLITE_OK) {
        sqlite3_close(source);
        throw DatabaseException("Could not open backup file '" + path + "'");
    }
    // Make sure it really is an LMS backup before we overwrite anything.
    sqlite3_stmt* stmt = nullptr;
    bool looksValid = false;
    if (sqlite3_prepare_v2(source,
                           "SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name IN "
                           "('app_user','submission','mark','audit_entry')",
                           -1, &stmt, nullptr) == SQLITE_OK &&
        sqlite3_step(stmt) == SQLITE_ROW) {
        looksValid = sqlite3_column_int(stmt, 0) == 4;
    }
    sqlite3_finalize(stmt);
    if (!looksValid) {
        sqlite3_close(source);
        throw DatabaseException("'" + path + "' is not an LMS backup file.");
    }
    try {
        copyDatabase(source, db_);
    } catch (...) {
        sqlite3_close(source);
        throw;
    }
    sqlite3_close(source);
}

// ---------------------------------------------------------------- Statement

Statement::Statement(Database& db, const char* sql) : db_(db) {
    if (sqlite3_prepare_v2(db_.handle(), sql, -1, &stmt_, nullptr) != SQLITE_OK) {
        fail(db_.handle(), "Could not prepare query");
    }
}

Statement::~Statement() {
    sqlite3_finalize(stmt_);
}

Statement& Statement::bind(int index, int value) {
    if (sqlite3_bind_int(stmt_, index, value) != SQLITE_OK) fail(db_.handle(), "Bind failed");
    return *this;
}

Statement& Statement::bind(int index, std::int64_t value) {
    if (sqlite3_bind_int64(stmt_, index, value) != SQLITE_OK) fail(db_.handle(), "Bind failed");
    return *this;
}

Statement& Statement::bind(int index, const std::string& value) {
    if (sqlite3_bind_text(stmt_, index, value.c_str(), static_cast<int>(value.size()),
                          SQLITE_TRANSIENT) != SQLITE_OK) {
        fail(db_.handle(), "Bind failed");
    }
    return *this;
}

Statement& Statement::bind(int index, const char* value) {
    return bind(index, std::string(value));
}

Statement& Statement::bindNull(int index) {
    if (sqlite3_bind_null(stmt_, index) != SQLITE_OK) fail(db_.handle(), "Bind failed");
    return *this;
}

Statement& Statement::bindOptional(int index, const std::optional<int>& value) {
    return value.has_value() ? bind(index, *value) : bindNull(index);
}

Statement& Statement::bindOptional(int index, const std::optional<std::string>& value) {
    return value.has_value() ? bind(index, *value) : bindNull(index);
}

Statement& Statement::bindTime(int index, TimePoint value) {
    return bind(index, toUnix(value));
}

Statement& Statement::bindOptionalTime(int index, const std::optional<TimePoint>& value) {
    return value.has_value() ? bindTime(index, *value) : bindNull(index);
}

bool Statement::step() {
    int rc = sqlite3_step(stmt_);
    if (rc == SQLITE_ROW) return true;
    if (rc == SQLITE_DONE) return false;
    fail(db_.handle(), "Query failed");
}

void Statement::run() {
    while (step()) {
        // ignore any rows
    }
}

int Statement::getInt(int col) const {
    return sqlite3_column_int(stmt_, col);
}

std::int64_t Statement::getInt64(int col) const {
    return sqlite3_column_int64(stmt_, col);
}

std::string Statement::getText(int col) const {
    const unsigned char* text = sqlite3_column_text(stmt_, col);
    return text != nullptr ? std::string(reinterpret_cast<const char*>(text)) : std::string();
}

bool Statement::isNull(int col) const {
    return sqlite3_column_type(stmt_, col) == SQLITE_NULL;
}

std::optional<int> Statement::getOptionalInt(int col) const {
    if (isNull(col)) return std::nullopt;
    return getInt(col);
}

std::optional<std::string> Statement::getOptionalText(int col) const {
    if (isNull(col)) return std::nullopt;
    return getText(col);
}

TimePoint Statement::getTime(int col) const {
    return fromUnix(getInt64(col));
}

std::optional<TimePoint> Statement::getOptionalTime(int col) const {
    if (isNull(col)) return std::nullopt;
    return getTime(col);
}

// ---------------------------------------------------------------- Transaction

Transaction::Transaction(Database& db) : db_(db) {
    db_.executeScript("BEGIN IMMEDIATE;");
}

Transaction::~Transaction() {
    if (!done_) {
        sqlite3_exec(db_.handle(), "ROLLBACK;", nullptr, nullptr, nullptr);
    }
}

void Transaction::commit() {
    db_.executeScript("COMMIT;");
    done_ = true;
}

}  // namespace lms
